if (lfs->free_count == 0) {
    return LFS_ERR_NOSPC;
}

lfs_block_t block = LFS_BLOCK_NULL;
lfs_size_t i = 0;

// Use lookahead buffer to find a free block
for (i = 0; i < lfs->cfg->lookahead_size; i++) {
    if (lfs->lookahead[i / 32] & (1U << (i % 32))) {
        block = lfs->lookahead_off + i;
        break;
    }
}

if (block == LFS_BLOCK_NULL) {
    // No free block found in lookahead, scan entire block range
    for (block = 0; block < lfs->block_count; block++) {
        bool found = false;
        for (i = 0; i < lfs->cfg->lookahead_size; i++) {
            if (lfs->lookahead[i / 32] & (1U << (i % 32)) && (lfs->lookahead_off + i) == block) {
                found = true;
                break;
            }
        }
        if (!found) {
            // Check if block is free by reading its tag
            lfs_cache_drop(lfs, &lfs->rcache);
            lfs_tag_t tag = 0;
            int err = lfs_bd_read(lfs, NULL, &lfs->rcache, sizeof(tag), block, 0, &tag, sizeof(tag));
            if (err) {
                continue;
            }
            if (tag == 0xffffffff) {
                break;
            }
        }
    }
    if (block == lfs->block_count) {
        return LFS_ERR_NOSPC;
    }
}

// Mark block as allocated
lfs->free_count--;

// Update lookahead buffer
lfs_size_t lookahead_idx = block - lfs->lookahead_off;
if (lookahead_idx < lfs->cfg->lookahead_size) {
    lfs->lookahead[lookahead_idx / 32] &= ~(1U << (lookahead_idx % 32));
}

// Update lookahead offset if needed
if (block == lfs->lookahead_off) {
    // Shift lookahead window
    lfs->lookahead_off++;
    for (i = 0; i < lfs->cfg->lookahead_size - 1; i++) {
        lfs->lookahead[i / 32] = (lfs->lookahead[i / 32] << 1) | ((lfs->lookahead[(i + 1) / 32] & 1) << 31);
    }
    lfs->lookahead[(lfs->cfg->lookahead_size - 1) / 32] <<= 1;
}

// Ensure lookahead buffer is refreshed if empty
if (lfs->free_count > 0 && lfs->lookahead_off + lfs->cfg->lookahead_size < lfs->block_count) {
    // Refresh lookahead buffer
    lfs->lookahead_off = lfs->lookahead_off + lfs->cfg->lookahead_size;
    for (i = 0; i < lfs->cfg->lookahead_size; i++) {
        lfs_block_t test_block = lfs->lookahead_off + i;
        if (test_block >= lfs->block_count) {
            break;
        }
        lfs_cache_drop(lfs, &lfs->rcache);
        lfs_tag_t tag = 0;
        int err = lfs_bd_read(lfs, NULL, &lfs->rcache, sizeof(tag), test_block, 0, &tag, sizeof(tag));
        if (err == 0 && tag == 0xffffffff) {
            lfs->lookahead[i / 32] |= (1U << (i % 32));
        }
    }
}

*block = block;
return LFS_ERR_OK;

